    const entry = await this.git(binding, ['ls-tree', commit, '--', file]);
    if (!/^100(?:644|755) blob /.test(entry) || entry.trimEnd().split('\n').length !== 1)
      throw Error('AGENT_CONTEXT_SOURCE_UNAVAILABLE: expected a regular Git file');
